'use strict';
const fs = require('node:fs');

function solve(input) {
  const values = input.trim().split(/\s+/).map(Number);
  const capacity = values[0];
  const dp = Array(capacity + 1).fill(false);
  dp[0] = true;
  for (const weight of values.slice(1)) {
    for (let j = capacity; j >= weight; j--) dp[j] = dp[j] || dp[j - weight];
  }
  return dp[capacity] ? 'YES' : 'NO';
}

