'use strict';
const fs = require('node:fs');

function solve(input) {
  const [n, m] = input.trim().split(/\s+/).map(Number);
  const digitSum = value => String(value).split('').reduce((sum, ch) => sum + Number(ch), 0);
  const values = Array.from({ length: n }, (_, i) => ({ value: i + 1, sum: digitSum(i + 1) }));
  values.sort((a, b) => a.sum - b.sum || a.value - b.value);
  return String(values[m - 1].value);
}

if (require.main === module) {
  process.stdout.write(solve(fs.readFileSync(0, 'utf8')) + '\n');
}
module.exports = { solve };
```

